(()=>{const essay=window.ESSAY_MEMORY_LESSONS["discuss-both-views:35"];if(!essay)throw Error('Missing exact source for discuss-both-views:35');essay.learningSentences=[{"paragraph":0,"index":0,"role":"Background（背景）","english":"Risk has always been part of sport, yet the question is whether the state should remove that risk by banning dangerous activities altogether.","chinese":"風險一直都是運動的一部分，然而問題在於，政府是否應該透過全面禁止危險活動來消除這種風險。","words":[["Risk",0,0.32],["has",0.32,0.54],["always",0.54,0.86],["been",0.86,1.12],["part",1.12,1.36],["of",1.36,1.48],["sport",1.48,1.76],["yet",2.292,2.432],["the",2.532,2.572],["question",2.572,2.912],["is",2.912,3.212],["whether",3.212,3.452],["the",3.452,3.672],["state",3.672,3.872],["should",3.872,4.132],["remove",4.132,4.432],["that",4.432,4.772],["risk",4.772,5.172],["by",5.172,5.732],["banning",5.732,6.052],["dangerous",6.052,6.632],["activities",6.632,7.252],["altogether",7.252,7.812]],"start":0,"end":8.593,"sourceIndices":[0]},{"paragraph":0,"index":1,"role":"Transition（轉折）","english":"While supporters of prohibition believe this would protect people from serious harm, I firmly believe that adults should remain free to choose such sports, provided that proper safety rules are enforced.","chinese":"雖然支持禁止的人認為這樣可以保護人們免受嚴重傷害，我堅定地認為，只要適當的安全規則得到執行，成年人仍然應該有自由選擇這類運動。","words":[["While",8.673,8.793],["supporters",8.793,9.113],["of",9.113,9.513],["prohibition",9.513,9.753],["believe",9.753,10.373],["this",10.373,10.753],["would",10.753,10.993],["protect",10.993,11.293],["people",11.293,11.653],["from",11.653,11.993],["serious",11.993,12.253],["harm",12.253,12.793],["I",13.453,13.533],["firmly",13.533,13.793],["believe",13.793,14.373],["that",14.373,14.573],["adults",14.573,14.813],["should",14.813,15.133],["remain",15.133,15.373],["free",15.373,15.773],["to",15.773,15.993],["choose",15.993,16.173],["such",16.173,16.493],["sports",16.493,16.873],["provided",17.413,17.773],["that",17.773,18.153],["proper",18.153,18.393],["safety",18.393,18.853],["rules",18.853,19.253],["are",19.253,19.593],["enforced",19.593,19.793]],"start":8.513,"end":21.089000000000002,"sourceIndices":[1,2]},{"paragraph":1,"index":0,"role":"Topic Sentence（主題句）","english":"Those who favour banning dangerous sports have a reasonable concern: some activities can lead to severe injury or death even when participants are experienced.","chinese":"支持禁止危險運動的人有一個合理的擔憂：有些活動即使參與者經驗豐富，也可能導致嚴重受傷或死亡。","words":[["Those",21.169,21.369],["who",21.369,21.549],["favour",21.549,21.789],["banning",21.789,22.209],["dangerous",22.209,22.849],["sports",22.849,23.329],["have",23.329,23.909],["a",23.909,23.989],["reasonable",23.989,24.389],["concern",24.389,24.969],["some",25.789,25.929],["activities",25.929,26.289],["can",26.289,26.829],["lead",26.829,27.049],["to",27.049,27.229],["severe",27.229,27.509],["injury",27.509,28.009],["or",28.009,28.509],["death",28.509,28.809],["even",28.809,29.469],["when",29.469,29.689],["participants",29.689,30.009],["are",30.009,30.489],["experienced",30.489,30.869]],"start":21.009,"end":31.821,"sourceIndices":[3]},{"paragraph":1,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Sports such as rock climbing, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","chinese":"攀岩、拳擊、賽車和跳傘等運動並不只是帶來輕微不適；一個錯誤便可造成永久性傷害。","words":[["Sports",31.901,32.101],["such",32.101,32.441],["as",32.441,32.601],["rock",32.601,32.841],["climbing",32.841,33.281],["boxing",33.761,34.161],["motor",34.661,34.801],["racing",34.801,35.201],["and",35.561,35.601],["skydiving",35.601,36.181],["do",36.181,36.721],["not",36.721,36.921],["merely",36.921,37.201],["involve",37.201,37.641],["mild",37.641,38.061],["discomfort",38.061,38.641],["one",39.561,39.601],["mistake",39.601,39.981],["can",39.981,40.281],["cause",40.281,40.541],["permanent",40.541,40.941],["damage",40.941,41.461]],"start":31.741,"end":42.149,"sourceIndices":[4]},{"paragraph":1,"index":2,"role":"Logic Chain（邏輯鏈）","english":"If an amateur climber ignores bad weather, for instance, rescue teams may have to risk their own lives to save him.","chinese":"例如，如果一名業餘攀岩者忽視惡劣天氣，救援隊可能不得不冒著自己的生命危險去拯救他。","words":[["If",42.229,42.329],["an",42.329,42.409],["amateur",42.409,42.649],["climber",42.649,43.269],["ignores",43.269,43.589],["bad",43.589,44.129],["weather",44.129,44.429],["for",44.969,45.069],["instance",45.069,45.409],["rescue",46.249,46.259],["teams",46.259,46.829],["may",46.829,47.069],["have",47.069,47.249],["to",47.249,47.389],["risk",47.389,47.609],["their",47.609,47.829],["own",47.829,48.069],["lives",48.069,48.289],["to",48.289,48.649],["save",48.649,48.869],["him",48.869,49.089]],"start":42.069,"end":49.660000000000004,"sourceIndices":[5]},{"paragraph":1,"index":3,"role":"Supporting Detail 2（支持細節二）","english":"In this sense, dangerous sports can create costs not only for the individual but also for families, medical services, and the wider community.","chinese":"從這個意義上說，危險運動不但可能令個人付出代價，也可能令家庭、醫療服務和更廣泛的社區承受負擔。","words":[["In",49.74,49.86],["this",49.86,49.98],["sense",49.98,50.28],["dangerous",50.58,51.06],["sports",51.06,51.54],["can",51.54,51.86],["create",51.86,52.16],["costs",52.16,52.52],["not",52.52,53.08],["only",53.08,53.28],["for",53.28,53.5],["the",53.5,53.62],["individual",53.62,54],["but",54,54.84],["also",54.84,55.04],["for",55.04,55.4],["families",55.4,55.84],["medical",56.36,56.52],["services",56.52,57.06],["and",57.76,57.8],["the",57.8,57.9],["wider",57.9,58.1],["community",58.1,58.5]],"start":49.580000000000005,"end":59.283,"sourceIndices":[6]},{"paragraph":1,"index":4,"role":"Conclusion（段落總結）","english":"From this perspective, a ban may seem like a simple way to prevent avoidable tragedy.","chinese":"從這個角度來看，禁令似乎是一種防止可避免悲劇的簡單方法。","words":[["From",59.363,59.503],["this",59.503,59.683],["perspective",59.683,60.163],["a",60.843,60.903],["ban",60.903,61.103],["may",61.103,61.383],["seem",61.383,61.643],["like",61.643,61.903],["a",61.903,62.023],["simple",62.023,62.243],["way",62.243,62.643],["to",62.643,62.843],["prevent",62.843,63.123],["avoidable",63.123,63.823],["tragedy",63.823,64.163]],"start":59.203,"end":65.209,"sourceIndices":[7]},{"paragraph":2,"index":0,"role":"Topic Sentence（主題句）","english":"However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains risk.","chinese":"然而，我認為這種論點走得太遠，因為個人自由不應該僅僅因為某項活動包含風險就被犧牲。","words":[["However",65.289,65.549],["I",65.949,66.109],["believe",66.109,66.389],["this",66.389,66.569],["argument",66.569,66.949],["goes",66.949,67.289],["too",67.289,67.529],["far",67.529,67.809],["because",67.809,68.249],["personal",68.249,68.549],["freedom",68.549,69.169],["should",69.169,69.489],["not",69.489,69.729],["be",69.729,69.869],["sacrificed",69.869,70.229],["simply",70.229,70.849],["because",70.849,71.729],["an",71.729,71.849],["activity",71.849,72.269],["contains",72.269,72.669],["risk",72.669,73.149]],"start":65.129,"end":73.872,"sourceIndices":[8]},{"paragraph":2,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Many meaningful human experiences, from travelling alone to starting a business, involve danger or uncertainty, but society does not ban them for that reason.","chinese":"許多有意義的人類經歷，從獨自旅行到創業，都包含危險或不確定性，但社會並不會因此禁止它們。","words":[["Many",73.952,74.212],["meaningful",74.212,74.712],["human",74.712,75.132],["experiences",75.132,75.872],["from",76.472,76.692],["travelling",76.692,77.012],["alone",77.012,77.472],["to",77.472,77.752],["starting",77.752,78.032],["a",78.032,78.212],["business",78.212,78.492],["involve",79.012,79.372],["danger",79.372,80.152],["or",80.152,80.532],["uncertainty",80.532,81.052],["but",81.792,81.972],["society",81.972,82.292],["does",82.292,82.812],["not",82.812,83.052],["ban",83.052,83.312],["them",83.312,83.532],["for",83.532,83.712],["that",83.712,83.872],["reason",83.872,84.172]],"start":73.792,"end":84.839,"sourceIndices":[9]},{"paragraph":2,"index":2,"role":"Logic Chain（邏輯鏈）","english":"A better response is strict regulation.","chinese":"更好的應對方法是嚴格監管。","words":[["A",84.919,84.999],["better",84.999,85.159],["response",85.159,85.619],["is",85.619,85.979],["strict",85.979,86.199],["regulation",86.199,86.679]],"start":84.759,"end":87.572,"sourceIndices":[10]},{"paragraph":2,"index":3,"role":"Example（例子）","english":"For example, skydiving centres can require professional instructors, medical checks, age limits, high-quality equipment, and emergency procedures.","chinese":"例如，跳傘中心可以要求專業教練、身體檢查、年齡限制、高質素裝備和緊急程序。","words":[["For",87.652,87.772],["example",87.772,88.072],["skydiving",88.692,89.032],["centres",89.032,89.492],["can",89.492,89.832],["require",89.832,90.152],["professional",90.152,90.772],["instructors",90.772,91.432],["medical",91.432,92.432],["checks",92.432,92.832],["age",93.412,93.512],["limits",93.512,93.892],["high-quality",94.412,94.872],["equipment",94.872,95.392],["and",95.752,95.812],["emergency",95.812,96.192],["procedures",96.192,96.952]],"start":87.492,"end":97.70700000000001,"sourceIndices":[11]},{"paragraph":2,"index":4,"role":"Logic Chain（邏輯鏈）","english":"These measures reduce unnecessary danger while still allowing people to test their courage, discipline, and physical limits.","chinese":"這些措施可以減少不必要的危險，同時仍然允許人們考驗自己的勇氣、紀律和身體極限。","words":[["These",97.787,97.947],["measures",97.947,98.267],["reduce",98.267,98.827],["unnecessary",98.827,99.367],["danger",99.367,100.107],["while",100.107,100.787],["still",100.787,101.027],["allowing",101.027,101.407],["people",101.407,101.827],["to",101.827,102.107],["test",102.107,102.327],["their",102.327,102.587],["courage",102.587,103.027],["discipline",103.527,103.807],["and",104.367,104.447],["physical",104.447,104.667],["limits",104.667,105.107]],"start":97.62700000000001,"end":105.816,"sourceIndices":[12]},{"paragraph":2,"index":5,"role":"Supporting Detail 2（支持細節二）","english":"If a sport is driven underground by a ban, it may become even less safe because participants will no longer operate under official supervision.","chinese":"如果一項運動因禁令而轉入地下，它可能會變得更加不安全，因為參與者將不再受到官方監管。","words":[["If",105.896,105.996],["a",105.996,106.036],["sport",106.036,106.376],["is",106.376,106.636],["driven",106.636,106.896],["underground",106.896,107.296],["by",107.296,107.776],["a",107.776,107.876],["ban",107.876,108.076],["it",108.616,108.796],["may",108.796,108.916],["become",108.916,109.196],["even",109.196,109.456],["less",109.456,109.756],["safe",109.756,110.116],["because",110.116,110.756],["participants",110.756,111.196],["will",111.196,111.676],["no",111.676,111.896],["longer",111.896,112.256],["operate",112.256,112.616],["under",112.616,113.076],["official",113.076,113.416],["supervision",113.416,113.876]],"start":105.736,"end":115.069,"sourceIndices":[13]},{"paragraph":3,"index":0,"role":"Reiterating Stance（重申立場）","english":"In conclusion, although dangerous sports can produce serious consequences, banning them is not the right solution.","chinese":"總結來說，雖然危險運動可能帶來嚴重後果，但禁止它們並不是正確的解決方法。","words":[["In",115.149,115.249],["conclusion",115.249,115.669],["although",116.269,116.569],["dangerous",116.569,117.029],["sports",117.029,117.549],["can",117.549,117.829],["produce",117.829,118.089],["serious",118.089,118.469],["consequences",118.469,119.129],["banning",119.929,120.149],["them",120.149,120.469],["is",120.469,120.789],["not",120.789,121.029],["the",121.029,121.209],["right",121.209,121.349],["solution",121.349,121.889]],"start":114.989,"end":122.538,"sourceIndices":[14]},{"paragraph":3,"index":1,"role":"Reiterating Arguments（重申論點）","english":"People should be allowed to take part in these activities because freedom, responsibility, and well-designed safety standards are a stronger answer than outright prohibition.","chinese":"人們應該被允許參與這些活動，因為自由、責任和設計良好的安全標準，比全面禁止更能有效回應這個問題。","words":[["People",122.618,122.858],["should",122.858,123.058],["be",123.058,123.178],["allowed",123.178,123.418],["to",123.418,123.638],["take",123.638,123.858],["part",123.858,124.118],["in",124.118,124.358],["these",124.358,124.458],["activities",124.458,124.818],["because",124.818,125.918],["freedom",125.918,126.518],["responsibility",126.998,127.618],["and",128.258,128.418],["well-designed",128.418,128.998],["safety",128.998,129.418],["standards",129.418,129.938],["are",129.938,130.618],["a",130.618,130.698],["stronger",130.698,131.018],["answer",131.018,131.398],["than",131.398,131.838],["outright",131.838,132.098],["prohibition",132.098,132.738]],"start":122.458,"end":133.138,"sourceIndices":[15]}];essay.meta={"topic":"政府應否禁止危險運動","summary":"禁令派指出重傷與救援社會成本；作者承認風險，但主張有安全規則的成人自由，並指出全面禁止可把活動推入地下。"};essay.support={"sentences":[{"simple":"Sport has always included some danger, but should the government remove that danger by stopping risky sports completely?","synonyms":[{"original":"Risk","simple":"danger","meaning":"風險"},{"original":"state","simple":"government","meaning":"政府"},{"original":"remove that risk","simple":"remove that danger","meaning":"消除風險"},{"original":"banning","simple":"stopping","meaning":"禁止"},{"original":"altogether","simple":"completely","meaning":"全面"}],"chunks":["Risk has always been part of sport,","yet the question is whether the state should","remove that risk by banning dangerous activities altogether."],"simpleChunks":["Sport has always included some danger,","but should the government remove that","danger by stopping risky sports completely?"]},{"simple":"Some think a ban would stop people being badly hurt. I think grown-ups should still be free to choose these sports if strong rules for safety are followed.","synonyms":[{"original":"supporters of prohibition","simple":"Some think a ban","meaning":"支持禁令者"},{"original":"serious harm","simple":"badly hurt","meaning":"嚴重傷害"},{"original":"adults","simple":"grown-ups","meaning":"成年人"},{"original":"free to choose","simple":"free to choose","meaning":"自由選擇"},{"original":"proper safety rules are enforced","simple":"strong rules for safety are followed","meaning":"執行安全規則"}],"chunks":["While supporters of prohibition believe this would protect","people from serious harm, I firmly believe that","adults should remain free to choose such sports,","provided that proper safety rules are enforced."],"simpleChunks":["Some think a ban would stop people","being badly hurt. I think grown-ups should","still be free to choose these sports","if strong rules for safety are followed."]},{"simple":"People who want to ban risky sports have a fair worry: even people who have done them for years can be badly hurt or killed.","synonyms":[{"original":"favour banning","simple":"want to ban","meaning":"支持禁止"},{"original":"reasonable concern","simple":"fair worry","meaning":"合理擔憂"},{"original":"severe injury or death","simple":"badly hurt or killed","meaning":"重傷或死亡"},{"original":"experienced","simple":"done them for years","meaning":"有經驗"}],"chunks":["Those who favour banning dangerous sports have a reasonable concern:","some activities can lead to severe","injury or death even when participants are experienced."],"simpleChunks":["People who want to ban risky","sports have a fair worry:","even people who have done them for","years can be badly hurt or killed."]},{"simple":"Climbing rocks, boxing, racing cars and jumping from planes are not just a little uncomfortable; one mistake can hurt someone for life.","synonyms":[{"original":"rock climbing","simple":"Climbing rocks","meaning":"攀岩"},{"original":"motor racing","simple":"racing cars","meaning":"賽車"},{"original":"skydiving","simple":"jumping from planes","meaning":"跳傘"},{"original":"mild discomfort","simple":"a little uncomfortable","meaning":"輕微不適"},{"original":"permanent damage","simple":"hurt someone for life","meaning":"永久傷害"}],"chunks":["Sports such as rock climbing, boxing,","motor racing, and skydiving do not merely involve mild discomfort;","one mistake can cause permanent damage."],"simpleChunks":["Climbing rocks, boxing, racing cars and jumping","from planes are not just a little uncomfortable;","one mistake can hurt someone for life."]},{"simple":"For example, if a person new to climbing ignores bad weather, the team that saves them may have to put their own lives in danger.","synonyms":[{"original":"amateur climber","simple":"person new to climbing","meaning":"業餘攀岩者"},{"original":"ignores bad weather","simple":"ignores bad weather","meaning":"忽視惡劣天氣"},{"original":"rescue teams","simple":"team that saves them","meaning":"救援隊"},{"original":"risk their own lives","simple":"put their own lives in danger","meaning":"冒生命危險"}],"chunks":["If an amateur climber ignores bad weather,","for instance, rescue teams may have to","risk their own lives to save him."],"simpleChunks":["For example, if a person","new to climbing ignores bad weather,","the team that saves them may","have to put their own lives in danger."]},{"simple":"So risky sports can cost not just the person taking part, but also their family, hospitals and other people in the area.","synonyms":[{"original":"In this sense","simple":"So","meaning":"從此意義"},{"original":"costs","simple":"cost","meaning":"代價"},{"original":"individual","simple":"person taking part","meaning":"參與者"},{"original":"medical services","simple":"hospitals","meaning":"醫療服務"},{"original":"wider community","simple":"other people in the area","meaning":"更廣社區"}],"chunks":["In this sense, dangerous sports can create costs","not only for the individual but also for families,","medical services, and the wider community."],"simpleChunks":["So risky sports can cost not","just the person taking part, but also their family,","hospitals and other people in the area."]},{"simple":"From this view, a ban can look like a simple way to stop tragedies that could have been prevented.","synonyms":[{"original":"From this perspective","simple":"From this view","meaning":"從此角度"},{"original":"ban","simple":"ban","meaning":"禁令"},{"original":"prevent avoidable tragedy","simple":"stop tragedies that could have been prevented","meaning":"防止可避免悲劇"}],"chunks":["From this perspective, a ban may seem","like a simple way to prevent avoidable tragedy."],"simpleChunks":["From this view, a ban can","look like a simple way to stop","tragedies that could have been prevented."]},{"simple":"But I think this idea goes too far because we should not take away personal choice just because an activity has some danger.","synonyms":[{"original":"However","simple":"But","meaning":"然而"},{"original":"goes too far","simple":"goes too far","meaning":"走得太遠"},{"original":"personal freedom","simple":"personal choice","meaning":"個人自由"},{"original":"sacrificed","simple":"take away","meaning":"被犧牲"},{"original":"contains risk","simple":"has some danger","meaning":"有風險"}],"chunks":["However, I believe this argument goes too far","because personal freedom should not be sacrificed simply","because an activity contains risk."],"simpleChunks":["But I think this idea goes too far","because we should not take away personal choice just","because an activity has some danger."]},{"simple":"Many things people value, such as travelling alone or starting a company, involve some danger or things we cannot be sure about, but we do not ban them for this reason.","synonyms":[{"original":"meaningful human experiences","simple":"things people value","meaning":"有意義經歷"},{"original":"travelling alone","simple":"travelling alone","meaning":"獨自旅行"},{"original":"starting a business","simple":"starting a company","meaning":"創業"},{"original":"uncertainty","simple":"things we cannot be sure about","meaning":"不確定"},{"original":"does not ban","simple":"do not ban","meaning":"不禁止"}],"chunks":["Many meaningful human experiences, from travelling alone to","starting a business, involve danger or uncertainty,","but society does not ban them for that reason."],"simpleChunks":["Many things people value, such as travelling","alone or starting a company, involve some","danger or things we cannot be sure about,","but we do not ban them for this reason."]},{"simple":"A better answer is to make and enforce strict rules.","synonyms":[{"original":"better response","simple":"better answer","meaning":"更好回應"},{"original":"strict regulation","simple":"make and enforce strict rules","meaning":"嚴格監管"}],"chunks":["A better response","is strict regulation."],"simpleChunks":["A better answer is to","make and enforce strict rules."]},{"simple":"For example, centres for jumping from planes can require trained teachers, health checks, a minimum age, good equipment and plans for emergencies.","synonyms":[{"original":"skydiving centres","simple":"centres for jumping from planes","meaning":"跳傘中心"},{"original":"professional instructors","simple":"trained teachers","meaning":"專業教練"},{"original":"medical checks","simple":"health checks","meaning":"體檢"},{"original":"age limits","simple":"minimum age","meaning":"年齡限制"},{"original":"high-quality equipment","simple":"good equipment","meaning":"高質素裝備"},{"original":"emergency procedures","simple":"plans for emergencies","meaning":"緊急程序"}],"chunks":["For example, skydiving centres can require professional instructors,","medical checks, age limits, high-quality equipment, and emergency procedures."],"simpleChunks":["For example, centres for jumping from planes","can require trained teachers, health checks, a minimum age,","good equipment and plans for emergencies."]},{"simple":"These rules can reduce danger people do not need to face while still letting them see how brave, careful and strong they can be.","synonyms":[{"original":"reduce unnecessary danger","simple":"reduce danger people do not need to face","meaning":"減少不必要危險"},{"original":"while still allowing","simple":"while still letting","meaning":"同時容許"},{"original":"courage","simple":"brave","meaning":"勇氣"},{"original":"discipline","simple":"careful","meaning":"紀律"},{"original":"physical limits","simple":"strong they can be","meaning":"身體極限"}],"chunks":["These measures reduce unnecessary danger while still allowing","people to test their courage, discipline, and physical limits."],"simpleChunks":["These rules can reduce danger people do not","need to face while still letting them see how brave,","careful and strong they can be."]},{"simple":"If a ban makes people do a sport in secret, it may become even more dangerous because officials can no longer check what happens.","synonyms":[{"original":"driven underground","simple":"do a sport in secret","meaning":"轉入地下"},{"original":"even less safe","simple":"even more dangerous","meaning":"更不安全"},{"original":"official supervision","simple":"officials can no longer check","meaning":"官方監管"}],"chunks":["If a sport is driven underground by a ban,","it may become even less safe","because participants will no longer operate under official supervision."],"simpleChunks":["If a ban makes people do a sport in secret,","it may become even more dangerous","because officials can no longer check what happens."]},{"simple":"To sum up, risky sports can cause serious harm, but a ban is not the best answer.","synonyms":[{"original":"In conclusion","simple":"To sum up","meaning":"總結"},{"original":"serious consequences","simple":"serious harm","meaning":"嚴重後果"},{"original":"banning them","simple":"a ban","meaning":"禁止"},{"original":"right solution","simple":"best answer","meaning":"正確方案"}],"chunks":["In conclusion, although dangerous sports can produce serious consequences,","banning them is not the right solution."],"simpleChunks":["To sum up, risky sports can cause serious harm,","but a ban is not the best answer."]},{"simple":"People should be able to do these sports because freedom, taking responsibility and well-made safety rules work better than a complete ban.","synonyms":[{"original":"allowed to take part","simple":"be able to do","meaning":"獲准參與"},{"original":"responsibility","simple":"taking responsibility","meaning":"責任"},{"original":"well-designed safety standards","simple":"well-made safety rules","meaning":"良好安全標準"},{"original":"outright prohibition","simple":"complete ban","meaning":"全面禁止"}],"chunks":["People should be allowed to take part in","these activities because freedom, responsibility, and well-designed safety","standards are a stronger answer than outright prohibition."],"simpleChunks":["People should be able to do these sports","because freedom, taking responsibility and well-made safety","rules work better than a complete ban."]}],"intro":[{"type":"quiz","prompt":"作者對危險運動禁令的看法是甚麼？","options":["反對全面禁止，支持嚴格安全監管。","支持任何運動都無規則。","支持一旦有風險便永久禁用。","認為救援人員從不承受風險。"],"correct":0,"why":"自由以安全規則為條件。"},{"type":"multi","prompt":"哪兩種後果需同時考慮？","detail":"選兩項，再按「確認」。","options":["參與者及救援者可能受傷。","禁令可把活動推向地下，失去監管。","所有風險必然完全可避免。","有禁令後不可能再有人參與。"],"correct":[0,1],"why":"風險與禁令的副作用都在範文。"}],"route":[{"type":"sequence","prompt":"還原四段討論","detail":"先尊重風險論，再分清監管與禁令。","items":[{"title":"引言","body":"風險存在，政策選擇是禁令或有條件自由。"},{"title":"禁令派","body":"重傷死亡和救援外部成本，禁令看似可避悲劇。"},{"title":"監管派","body":"其他有風險經驗亦不禁；具體安全規則可降風險，禁令或轉地下。"},{"title":"結論","body":"承認嚴重後果，仍選自由責任與安全標準。"}],"why":"接受反方風險不代表必須接受其禁令。"}],"evidence":[{"type":"quiz","prompt":"反方指出甚麼嚴重後果？","options":["有經驗者亦可重傷死亡，救援隊也可能冒險。","所有參與者只會有輕微不適。","救援隊永遠不用出動。","風險只會影響運動器材外觀。"],"correct":0,"why":"個人與第三者風險均被提出。"},{"type":"quiz","prompt":"作者為何提獨自旅行和創業？","options":["兩者也有風險，但社會並不因此全面禁止。","證明所有旅行都比跳傘危險。","證明創業必然沒有任何不確定。","只想比較交通工具的價格。"],"correct":0,"why":"用類比測試禁止原則。"},{"type":"quiz","prompt":"跳傘中心可採哪幾項措施？","options":["教練、體檢、年齡限制、裝備與緊急程序。","只張貼一張沒有內容的海報。","只規定所有人必須跳傘。","取消一切官方安全檢查。"],"correct":0,"why":"監管可具體執行。"},{"type":"quiz","prompt":"禁令為何可能反令活動更危險？","options":["轉入地下後參與者可能失去官方監督。","禁令必然保證所有人立即守法。","地下活動必然比合法活動更容易監管。","禁令會自動提升每件裝備品質。"],"correct":0,"why":"禁止的副作用需考慮。"},{"type":"quiz","prompt":"結論如何平衡自由與安全？","options":["成年人可參與，並由責任及安全標準降低危險。","只保留自由，完全不執行安全規則。","只保留禁令，完全不考慮成人選擇。","把所有運動風險說成不存在。"],"correct":0,"why":"provided that 是核心限制。"}],"logic":[{"type":"sequence","prompt":"風險與外部成本","detail":"先尊重風險論，再分清監管與禁令。","items":[{"title":"活動風險","body":"一個錯誤或造成永久傷害。"},{"title":"救援例子","body":"壞天氣出事，救援隊也需冒險。"},{"title":"社會成本","body":"家庭、醫療與社區同受影響。"},{"title":"反方推論","body":"禁令似乎可避免悲劇。"}],"why":"先準確呈現禁令派的理由。"},{"type":"sequence","prompt":"監管替代禁令","detail":"先尊重風險論，再分清監管與禁令。","items":[{"title":"原則","body":"有風險不自動等於全面禁止。"},{"title":"措施","body":"教練體檢年齡裝備與應急程序。"},{"title":"雙重結果","body":"減不必要風險，保留成人選擇。"},{"title":"禁令副作用","body":"活動轉地下後或更難監督。"}],"why":"安全規範與自由可並存。"}],"structures":[{"id":"model-essay-35-ielts-discuss-both-views-frame-01","frame":"Risk has always been part of [有風險的活動], yet the question is whether the state should remove that risk by banning [可能被禁的活動] altogether.","meaning":"運動本有風險，問題是政府應否全面禁止。","usage":"當你要由某活動本有風險，提出政府應否全面禁止的政策問題時。","source":{"paragraph":1,"sentence":1},"parts":[{"text":"Risk has always been part of ","kind":"link","label":"句型固定部分"},{"text":"sport","kind":"slot","label":"有風險的活動"},{"text":", yet the question is whether the state should remove that risk by banning ","kind":"link","label":"句型固定部分"},{"text":"dangerous activities","kind":"slot","label":"可能被禁的活動"},{"text":" altogether.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","While supporters of prohibition believe this would protect people from serious harm, I firmly believe that adults should remain free to choose difficult journeys, provided that proper safety rules are enforced.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty."],"correct":0,"explanations":["這句yet 把普遍風險轉成是否全面禁止的政策問題，用法與原文一致。","這句While 承認保護論，provided that 加選擇自由的安全條件；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-02","frame":"While [支持禁止的理由], I firmly believe that adults should remain free to choose [受爭議的活動], provided that [應執行的安全條件].","meaning":"作者支持成年人自由選，條件是安全規則執行。","usage":"當你要用 While 承認保護理由，再用 provided that 為自由加條件時。","source":{"paragraph":1,"sentence":2},"parts":[{"text":"While ","kind":"link","label":"句型固定部分"},{"text":"supporters of prohibition believe this would protect people from serious harm","kind":"slot","label":"支持禁止的理由"},{"text":", I firmly believe that adults should remain free to choose ","kind":"link","label":"句型固定部分"},{"text":"such sports","kind":"slot","label":"受爭議的活動"},{"text":", provided that ","kind":"link","label":"句型固定部分"},{"text":"proper safety rules are enforced","kind":"slot","label":"應執行的安全條件"},{"text":".","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["While supporters of prohibition believe this would protect people from serious harm, I firmly believe that adults should remain free to choose difficult journeys, provided that proper safety rules are enforced.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty."],"correct":0,"explanations":["這句While 承認保護論，provided that 加選擇自由的安全條件，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-03","frame":"Those who favour banning [被主張禁止的活動] have a reasonable concern: some activities can lead to severe injury or death even when participants are experienced.","meaning":"有經驗者也可重傷甚至死亡。","usage":"當你要先公平說明反方的嚴重後果擔憂時。","source":{"paragraph":2,"sentence":1},"parts":[{"text":"Those who favour banning ","kind":"link","label":"句型固定部分"},{"text":"dangerous sports","kind":"slot","label":"被主張禁止的活動"},{"text":" have a reasonable concern: some activities can lead to severe injury or death even when participants are experienced.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Those who favour banning dangerous journeys have a reasonable concern: some activities can lead to severe injury or death even when participants are experienced.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句冒號公平展開反方合理傷害憂慮，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-04","frame":"Sports such as [首項高風險運動], boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","meaning":"攀岩拳擊賽車跳傘一失誤或永久受傷。","usage":"當你要用 not merely ...; ... 說明風險可能超過輕微不適時。","source":{"paragraph":2,"sentence":2},"parts":[{"text":"Sports such as ","kind":"link","label":"句型固定部分"},{"text":"rock climbing","kind":"slot","label":"首項高風險運動"},{"text":", boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句not merely ...; ... 強調錯誤後果可永久，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-05","frame":"If [參與者] ignores [危險訊號], for instance, rescue teams may have to risk their own lives to save him.","meaning":"業餘攀岩者忽略天氣，可令救援隊冒險。","usage":"當你要用 If 例子顯示個人冒險也可能讓第三者承擔風險時。","source":{"paragraph":2,"sentence":3},"parts":[{"text":"If ","kind":"link","label":"句型固定部分"},{"text":"an amateur climber","kind":"slot","label":"參與者"},{"text":" ignores ","kind":"link","label":"句型固定部分"},{"text":"bad weather","kind":"slot","label":"危險訊號"},{"text":", for instance, rescue teams may have to risk their own lives to save him.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["If an amateur sailor ignores bad weather, for instance, rescue teams may have to risk their own lives to save him.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句If 例子展示救援者也承受風險，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-06","frame":"In this sense, [帶外部成本的活動] can create costs not only for the individual but also for families, medical services, and the wider community.","meaning":"傷害成本不只個人，亦有家庭醫療和社區。","usage":"當你要用 not only ... but also ... 擴展個人成本到家庭社會時。","source":{"paragraph":2,"sentence":4},"parts":[{"text":"In this sense, ","kind":"link","label":"句型固定部分"},{"text":"dangerous sports","kind":"slot","label":"帶外部成本的活動"},{"text":" can create costs not only for the individual but also for families, medical services, and the wider community.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In this sense, dangerous journeys can create costs not only for the individual but also for families, medical services, and the wider community.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句not only ... but also 擴大個人風險到社會成本，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-07","frame":"From this perspective, a ban may seem like a simple way to prevent avoidable [欲避免的後果]","meaning":"禁令似能阻止可避免悲劇。","usage":"當你已列風險，需公平概括禁令為何看似簡單有效時。","source":{"paragraph":2,"sentence":5},"parts":[{"text":"From this perspective, a ban may seem like a simple way to prevent avoidable ","kind":"link","label":"句型固定部分"},{"text":"tragedy.","kind":"slot","label":"欲避免的後果"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["From this perspective, a ban may seem like a simple way to prevent avoidable accidents.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句From this perspective 公平概括禁令吸引力，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句because 指出有風險不自動足以剝奪自由；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-08","frame":"However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains [活動所含風險]","meaning":"作者反對只因有風險便犧牲自由。","usage":"當你要指出「有風險」不足以自動推導全面剝奪選擇時。","source":{"paragraph":3,"sentence":1},"parts":[{"text":"However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains ","kind":"link","label":"句型固定部分"},{"text":"risk.","kind":"slot","label":"活動所含風險"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["However, I believe this argument goes too far because personal freedom should not be sacrificed simply because an activity contains uncertainty.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句because 指出有風險不自動足以剝奪自由，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-09","frame":"Many meaningful human experiences, from [另一有風險經驗] to starting a business, involve danger or uncertainty, but society does not ban them for that reason.","meaning":"獨遊創業有風險，社會也不因此禁止。","usage":"當你要用其他同樣有風險的活動測試一條禁令原則時。","source":{"paragraph":3,"sentence":2},"parts":[{"text":"Many meaningful human experiences, from ","kind":"link","label":"句型固定部分"},{"text":"travelling alone","kind":"slot","label":"另一有風險經驗"},{"text":" to starting a business, involve danger or uncertainty, but society does not ban them for that reason.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Many meaningful human experiences, from hiking alone to starting a business, involve danger or uncertainty, but society does not ban them for that reason.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句from ... to ... 用其他有風險經驗測試禁令邏輯，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-10","frame":"A better response is [比禁令好的做法]","meaning":"作者選嚴格監管。","usage":"當你要以短主題句提出比禁令更合比例的替代方案時。","source":{"paragraph":3,"sentence":3},"parts":[{"text":"A better response is ","kind":"link","label":"句型固定部分"},{"text":"strict regulation.","kind":"slot","label":"比禁令好的做法"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["A better response is careful regulation.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句短主題句提出監管取代禁令，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-11","frame":"For example, [有監管責任的機構] centres can require professional instructors, medical checks, age limits, high-quality equipment, and emergency procedures.","meaning":"跳傘中心可設教練體檢年齡裝備緊急程序。","usage":"當你要列出一組具體且可執行的安全要求時。","source":{"paragraph":3,"sentence":4},"parts":[{"text":"For example, ","kind":"link","label":"句型固定部分"},{"text":"skydiving","kind":"slot","label":"有監管責任的機構"},{"text":" centres can require professional instructors, medical checks, age limits, high-quality equipment, and emergency procedures.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["For example, diving centres can require professional instructors, medical checks, age limits, high-quality equipment, and emergency procedures.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句例子列五項可執行安全要求，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-12","frame":"These measures reduce unnecessary danger while still allowing people to test their [可測試的第一能力], discipline, and physical limits.","meaning":"規則減危險，仍容許考驗勇氣紀律身體。","usage":"當你要用 while 同時保留參與機會並降低不必要危險時。","source":{"paragraph":3,"sentence":5},"parts":[{"text":"These measures reduce unnecessary danger while still allowing people to test their ","kind":"link","label":"句型固定部分"},{"text":"courage","kind":"slot","label":"可測試的第一能力"},{"text":", discipline, and physical limits.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["These measures reduce unnecessary danger while still allowing people to test their judgement, discipline, and physical limits.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句while 並列減風險與保留體驗，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-13","frame":"If [活動] is driven underground by a ban, it may become even less safe because [監管消失]","meaning":"禁令可令活動轉地下，失監管更不安全。","usage":"當你要用 If 說明禁止可能把活動推入更難監督的地方時。","source":{"paragraph":3,"sentence":6},"parts":[{"text":"If ","kind":"link","label":"句型固定部分"},{"text":"a sport","kind":"slot","label":"活動"},{"text":" is driven underground by a ban, it may become even less safe because ","kind":"link","label":"句型固定部分"},{"text":"participants will no longer operate under official supervision.","kind":"slot","label":"監管消失"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["If a pastime is driven underground by a ban, it may become even less safe because participants will no longer operate under official supervision.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution."],"correct":0,"explanations":["這句If 禁令轉地下可失官方監管而更危險，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句although 承認後果，仍否定禁令；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-14","frame":"In conclusion, although dangerous [被討論的高風險活動] can produce serious consequences, banning them is not the right solution.","meaning":"危險運動後果嚴重，禁令仍非正解。","usage":"當結論要承認後果嚴重，仍判全面禁止不適當時。","source":{"paragraph":4,"sentence":1},"parts":[{"text":"In conclusion, although dangerous ","kind":"link","label":"句型固定部分"},{"text":"sports","kind":"slot","label":"被討論的高風險活動"},{"text":" can produce serious consequences, banning them is not the right solution.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In conclusion, although dangerous journeys can produce serious consequences, banning them is not the right solution.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","Many meaningful human experiences, from hiking alone to starting a business, involve danger or uncertainty, but society does not ban them for that reason."],"correct":0,"explanations":["這句although 承認後果，仍否定禁令，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句from ... to ... 用其他有風險經驗測試禁令邏輯；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-35-ielts-discuss-both-views-frame-15","frame":"People should be allowed to take part in [受爭議的活動] because [保留活動的理由] are a stronger answer than [全面禁止].","meaning":"自由責任及良好安全標準勝全面禁止。","usage":"當你要用 because 比較有條件自由與全面禁止何者更有效時。","source":{"paragraph":4,"sentence":2},"parts":[{"text":"People should be allowed to take part in ","kind":"link","label":"句型固定部分"},{"text":"these activities","kind":"slot","label":"受爭議的活動"},{"text":" because ","kind":"link","label":"句型固定部分"},{"text":"freedom, responsibility, and well-designed safety standards","kind":"slot","label":"保留活動的理由"},{"text":" are a stronger answer than ","kind":"link","label":"句型固定部分"},{"text":"outright prohibition","kind":"slot","label":"全面禁止"},{"text":".","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["People should be allowed to take part in these activities because freedom, responsibility, and well-designed safety standards are a stronger answer than a complete ban.","Risk has always been part of travel, yet the question is whether the state should remove that risk by banning dangerous journeys altogether.","Sports such as mountain biking, boxing, motor racing, and skydiving do not merely involve mild discomfort; one mistake can cause permanent damage.","Many meaningful human experiences, from hiking alone to starting a business, involve danger or uncertainty, but society does not ban them for that reason."],"correct":0,"explanations":["這句because 結論比較自由責任安全與全面禁止，用法與原文一致。","這句yet 把普遍風險轉成是否全面禁止的政策問題；它並非本題要辨認的句型及功能。","這句not merely ...; ... 強調錯誤後果可永久；它並非本題要辨認的句型及功能。","這句from ... to ... 用其他有風險經驗測試禁令邏輯；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"}],"transfer":[{"prompt":"哪句呈現反方最強憂慮？","context":"業餘攀岩者無視暴雨，救援隊被迫進山。","question":"哪句呈現反方最強憂慮？","options":["參與者失誤也可能讓救援人員承擔生命風險。","參與者自己選擇冒險，因此救援風險主要由他承擔。","救援人員有經驗，暴雨中的行動應視作日常工作。","攀岩者失誤造成救援開支，但不影響隊員的人身安全。"],"correct":0,"explanations":["外部風險是反方理由。","選擇由個人作出，救援風險卻可能落到他人身上。","經驗不能消除惡劣天氣的人身風險。","救援隊員的生命風險不能只算成費用。"],"why":"外部風險是反方理由。","sourceSentenceIndices":[4,5],"modelLink":"amateur climber→rescue risk。"},{"prompt":"哪句避免直接跳到全面禁令？","context":"一項高風險運動有嚴重受傷案例。","question":"哪句避免直接跳到全面禁令？","options":["應比較風險與安全規管，不能只因有風險便禁。","傷害案例說明要加強勸告，運動規則則可維持原樣。","若傷害可能嚴重，先全面禁運動，再討論安全安排。","成年人有選擇自由，故風險評估只需由個人完成。"],"correct":0,"explanations":["風險不自動推出禁令。","若不改規則，難以有效回應已見傷害。","傷害可能發生仍不足以直接全面禁止。","個人自由之外仍有公共安全後果。"],"why":"風險不自動推出禁令。","sourceSentenceIndices":[7,8,9],"modelLink":"risk alone insufficient for ban。"},{"prompt":"哪句提供具體監管做法？","context":"跳傘中心想降低風險而保留成人參與。","question":"哪句提供具體監管做法？","options":["可設專業教練、現場體檢、年齡限制與緊急程序。","可增設教練和現場說明，體檢與緊急程序稍後再談。","可限制年齡和增加保險，裝備與教練則由個人決定。","可檢查裝備與健康，教練資格及應急安排仍可省略。"],"correct":0,"explanations":["具體可執行規則。","完整方案還須體檢與緊急程序。","保險不能取代教練和裝備的風險預防。","教練和應急安排也屬安全制度核心。"],"why":"具體可執行規則。","sourceSentenceIndices":[10,11],"modelLink":"instructors/medical/age/emergency。"},{"prompt":"哪句分析禁令副作用？","context":"某地禁止一項運動後，參與者改在秘密場所進行。","question":"哪句分析禁令副作用？","options":["轉入地下可能令官方更難監督，活動反而更危險。","禁令減少公開場地，因此官方更容易掌握剩餘活動。","秘密場所可避開申報程序，風險主要來自參與者技術。","轉到地下後仍可照常檢查裝備，監督問題不必討論。"],"correct":0,"explanations":["地下化可削弱監督。","轉入地下通常令活動更難監督。","申報減少本身就是監督風險。","地下場所未必接受日常裝備檢查。"],"why":"地下化可削弱監督。","sourceSentenceIndices":[12],"modelLink":"underground→less official supervision。"},{"prompt":"哪句能轉用本文框架？","context":"另一題討論是否禁止高風險戶外旅行。","question":"哪句能轉用本文框架？","options":["可考慮個人選擇自由、救援成本及安全許可制度。","可比較個人自由與旅遊收入，卻不談救援人員風險。","可衡量戶外樂趣與場地租金，卻略過安全許可制度。","可討論救援開支與宣傳效果，但不評估成年人的選擇。"],"correct":0,"explanations":["自由、外部成本及監管可跨題。","救援風險是這道題要衡量的公共成本。","場地租金不能代替救援和安全制度。","政策仍須權衡成人選擇權。"],"why":"自由、外部成本及監管可跨題。","sourceSentenceIndices":[5,7,10,12],"modelLink":"external costs plus regulation。"},{"prompt":"哪句指出誤解？","context":"有人說「只要准許，就表示政府可不管安全」。","question":"哪句指出誤解？","options":["允許參與可以安全規則獲執行為前提，而非放任。","政府可准許參與，安全規則則交由中心自行選擇執行。","成年人可自願參與，但教練和體檢只作參考建議。","安全制度有助減風險，故准許參與即可停止監督。"],"correct":0,"explanations":["provided that 設條件。","規則須實際執行，不能只交中心自由決定。","體檢和教練若只屬建議，保障不足。","准許活動後仍需要監督規則。"],"why":"provided that 設條件。","sourceSentenceIndices":[1,10,11],"modelLink":"free choice provided safety rules enforced。"},{"prompt":"哪句補足？","context":"作文只說「危險運動有代價」，未說代價給誰。","question":"哪句補足？","options":["個人、家人、醫療系統和社區都可能分擔後果。","參與者和保險公司會付費，家人及社區則不受波及。","傷者需醫療服務，但救援者的危險可留待之後分析。","家人可能擔心，醫療和社區成本則由個人處理。"],"correct":0,"explanations":["not only individual but also community。","家人和社區也可能承受後果。","救援人員風險正是需說清的成本。","醫療與社區並不只由個人承擔。"],"why":"not only individual but also community。","sourceSentenceIndices":[5],"modelLink":"costs not only individual。"},{"prompt":"其論證功能是甚麼？","context":"有人用獨自旅行和創業作類比。","question":"其論證功能是甚麼？","options":["指出有風險的有價值活動並非都應被全面禁止。","類比說明創業也有風險，因此運動應用相同安全規則。","旅行和創業都有收益，故運動風險可交由市場處理。","類比支持保留選擇，但未說明運動為何仍需規管。"],"correct":0,"explanations":["類比檢驗禁令原則。","不同活動需要按自身風險設計規則。","市場收益不能取代安全監管。","類比須同時支持自由與適當規管。"],"why":"類比檢驗禁令原則。","sourceSentenceIndices":[8],"modelLink":"other risky experiences not banned。"},{"prompt":"哪句可提供較合比例方案？","context":"一份政策只寫「禁止」而沒有其他選擇。","question":"哪句可提供較合比例方案？","options":["用教練、體檢、裝備及緊急程序降低不必要危險。","以入場聲明提醒風險，教練與體檢則由參與者決定。","只增加裝備規格，對健康狀況和應急程序不作安排。","由場地安排緊急聯絡，日常教練監督可暫時省略。"],"correct":0,"explanations":["監管具體對準風險。","聲明不能代替教練與體檢。","只管裝備，仍漏掉健康和緊急程序。","應急聯絡不能取代持續的教練指導。"],"why":"監管具體對準風險。","sourceSentenceIndices":[9,10,11],"modelLink":"strict regulation as better response。"},{"prompt":"哪句最完整？","context":"結論須承認危險又拒絕全面禁止。","question":"哪句最完整？","options":["嚴重傷害確有可能，但有條件自由與安全規範較合適。","傷害值得關注，故先暫停活動，安全制度待日後再議。","成年人可自由參與，嚴重傷害則交由保險處理。","有規則便可降低風險，所以結論可少談及危險。"],"correct":0,"explanations":["although 承認後果，選替代方案。","結論要選有條件准許，不只是延後決定。","保險不能取代預防傷害的規範。","規則減低危險，不能說危險不存在。"],"why":"although 承認後果，選替代方案。","sourceSentenceIndices":[13,14],"modelLink":"serious consequence but not ban。"}],"mediumExtras":[]};})();
